def transform(grid):
    # The four separated patches encode a single pattern by overlaying them
    # at their respective bounding-box origins; choose the largest patch.
    pts={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x}
    comps=[]
    while pts:
        s=pts.pop(); q=[s]; co={s}
        while q:
            r,c=q.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    p=(r+dr,c+dc)
                    if p in pts: pts.remove(p);co.add(p);q.append(p)
        comps.append(co)
    # upper-left component is the source pattern in demonstrations
    co=min(comps,key=lambda s:min((r,c) for r,c in s))
    r0=min(r for r,c in co);r1=max(r for r,c in co);c0=min(c for r,c in co);c1=max(c for r,c in co)
    return [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
